import CoreBluetooth
class Scanner: NSObject, CBCentralManagerDelegate {
  var central: CBCentralManager!
  override init() { super.init(); central = CBCentralManager(delegate: self, queue: nil) }
  func centralManagerDidUpdateState(_ c: CBCentralManager) {
    if c.state == .poweredOn {
      c.scanForPeripherals(withServices: [CBUUID(string: "{{service_uuid}}")])
    }
  }
  func centralManager(_ c: CBCentralManager, didDiscover p: CBPeripheral, advertisementData: [String: Any], rssi RSSI: NSNumber) {
    print("found", p.name ?? "?", RSSI)
  }
}
